const bars=r=>`<div class="bars">${r.map(([l,v])=>`<div class="r"><span>${esc(l)}</span><div class="tr"><i class="c${cls(v)[0]}" style="width:${v/5*100}%"></i></div><b>${v.toFixed(1)}</b></div>`).join('')}</div>`;
