/* ---- modal ---- */
const optHtml=(o,v)=>{const a=Array.isArray(o)?o:[o,o];return`<option value="${esc(a[0])}"${String(a[0])===String(v)?' selected':''}>${esc(a[1])}</option>`};
const fld=(f,v)=>{v=v??f.d??'';const w=f.w?' class="w"':'',hint=f.h?`<small class="sm">${f.h}</small>`:'';
 if(f.t==='select')return`<div${w}><label>${f.l}</label><select name="${f.n}">${f.o.map(o=>o&&o.g?`<optgroup label="${esc(o.g)}">${o.o.map(x=>optHtml(x,v)).join('')}</optgroup>`:optHtml(o,v)).join('')}</select>${hint}</div>`;
 if(f.t==='textarea')return`<div${w}><label>${f.l}</label><textarea name="${f.n}"${f.r?' required':''}>${esc(v)}</textarea>${hint}</div>`;
 const inp=`<input name="${f.n}" type="${f.t||'text'}" value="${esc(v)}"${f.r?' required':''}${f.t==='number'?' step="any" min="0"':''}${f.t==='password'?' autocomplete="new-password"':''}${f.ph?` placeholder="${esc(f.ph)}"`:''}>`;
 return`<div${w}><label>${f.l}</label>${f.t==='password'?`<div class="pw">${inp}<button type="button" class="btn sm" data-pw="show">Mostrar</button>${f.gen?'<button type="button" class="btn sm" data-pw="gen">Gerar senha</button>':''}</div>`:inp}${hint}</div>`};
function modal(title,fields,ok,vals={},intro='',btn='Salvar'){const d=document.createElement('dialog');
 d.innerHTML=`<form class="mform"><h3>${esc(title)}</h3>${intro}<div class="grid2">${fields.map(f=>fld(f,vals[f.n])).join('')}</div><p class="err" role="alert" style="color:#b3261e;margin:10px 0 0"></p><div class="mact"><button type="button" class="btn ghost" data-x>Cancelar</button><button class="btn pri">${esc(btn)}</button></div></form>`;
 document.body.appendChild(d);d.showModal();$('[data-x]',d).onclick=()=>d.close();d.onclose=()=>d.remove();
 $('form',d).onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target),o={};fields.forEach(f=>o[f.n]=fd.get(f.n));try{await ok(o);d.close();go()}catch(x){$('.err',d).textContent=x.message}}}
/* ---- login ---- */
function loginView(msg='',force=false){
 root.innerHTML=`<div class="lg"><div class="box"><img src="assets/logo.png" alt="Acella"><h1>${force?'Defina sua nova senha':'Área restrita'}</h1><p class="sm">${force?'Por segurança, troque a senha provisória (mín. 10 caracteres, com letras e números).':'Acesso individual e auditado.'}</p>
 <form id="f">${force?`<label for="a">Senha atual</label><input id="a" type="password" required><label for="n" style="margin-top:10px">Nova senha</label><input id="n" type="password" minlength="10" required autocomplete="new-password">`:`<label for="e">E-mail ou usuário</label><input id="e" type="text" required autocomplete="username"><label for="p" style="margin-top:10px">Senha</label><input id="p" type="password" required autocomplete="current-password">`}
 <div class="err" role="alert">${esc(msg)}</div><button class="btn pri" style="width:100%">${force?'Salvar e entrar':'Entrar'}</button></form>${force?'<p class="sm" style="margin-top:14px"><a href="#" id="vs">Sair e voltar ao site</a></p>':'<p class="sm" style="margin-top:14px">Esqueceu a senha? Solicite a redefinição ao administrador. · <a href="index.html">Voltar ao site</a></p>'}</div></div>`;
 if($('#vs'))$('#vs').onclick=async e=>{e.preventDefault();try{await api('POST','/api/logout')}catch(x){}ME=null;location.href='index.html'};
 $('#f').onsubmit=async e=>{e.preventDefault();try{if(force){await api('POST','/api/password',{atual:$('#a').value,nova:$('#n').value});ME.must_change=false;start()}else{ME=await api('POST','/api/login',{email:$('#e').value,password:$('#p').value});ME.must_change?loginView('',true):start()}}catch(x){loginView(x.message,force)}}}
