const CF=[{n:'cnpj',l:'CNPJ',r:1},{n:'razao',l:'Razão social',r:1},{n:'fantasia',l:'Nome fantasia'},{n:'responsavel',l:'Responsável'},{n:'contato',l:'Contato (e-mail/telefone)'},{n:'mensalidade',l:'Valor da mensalidade a faturar (R$/mês)',t:'number'},{n:'plano',l:'Plano contratado',t:'select',o:[['','—'],['Essencial','Essencial'],['Equilíbrio','Equilíbrio'],['Completo','Completo']]},{n:'funcionarios',l:'Funcionários contratados',t:'number'},{n:'preco_func',l:'Preço por funcionário (R$/mês)',t:'number'},{n:'inicio_contrato',l:'Início do contrato',t:'month'},{n:'valor_km',l:'Valor do km rodado (R$/km)',t:'number'},{n:'limite_atend_mes',l:'Limite de atendimentos por pessoa no mês (0 = sem limite)',t:'number'},{n:'valor_excedente',l:'Valor por atendimento excedente (R$)',t:'number'},{n:'endereco',l:'Endereço',w:1}];
