const fileB64=f=>new Promise((ok,no)=>{const r=new FileReader();r.onload=()=>ok(String(r.result).split(',')[1]||'');r.onerror=()=>no(new Error('Não foi possível ler o arquivo.'));r.readAsDataURL(f)});
const genPw=()=>{const A='abcdefghjkmnpqrstuvwxyzABCDEFGHJKLMNPQRSTUVWXYZ',N='23456789',pick=(s,n)=>[...crypto.getRandomValues(new Uint32Array(n))].map(x=>s[x%s.length]),c=[...pick(A,7),...pick(N,3),...pick(A+N,2)],r=crypto.getRandomValues(new Uint32Array(c.length));for(let i=c.length-1;i>0;i--){const j=r[i]%(i+1);[c[i],c[j]]=[c[j],c[i]]}return c.join('')};
document.addEventListener('click',e=>{const t=e.target.closest('[data-pw]');if(!t)return;e.preventDefault();const i=t.closest('.pw').querySelector('input');if(t.dataset.pw==='gen'){i.value=genPw();i.type='text'}else i.type=i.type==='password'?'text':'password'});
