 d.innerHTML=`<div class="mform"><h3>${esc(o.titulo)}</h3>${o.nota?`<p class="sm">${o.nota}</p>`:''}<div id="pkpre"></div><div class="pkrow"><input id="pks" placeholder="Buscar por nome, CPF ou cargo…" autocomplete="off"><select id="pkc"><option value="">Todas as empresas</option>${cl.filter(c=>c.ativo!==0).map(c=>`<option value="${c.id}"${String(c.id)===String(o.cliente||'')?' selected':''}>${esc(c.fantasia)}</option>`).join('')}</select></div><div class="pklist" id="pkl"></div><p class="sm" style="margin-top:8px">Colaborador não está na lista? Cadastre ou importe em <b>Colaboradores</b> e volte aqui.</p><div class="mact"><button class="btn ghost" id="pkx" type="button">Cancelar</button></div></div>`;
 document.body.appendChild(d);d.showModal();const done=v=>{if(!fim){fim=true;res(v)}d.close()};d.onclose=()=>{d.remove();if(!fim){fim=true;res(null)}};
