 document.body.appendChild(d);d.showModal();d.onclose=()=>{d.remove();go()};
 const $d=s=>$(s,d),corpo=()=>({tipo,client_id:+$d('#imc').value,arquivo:arq.b64,nome_arquivo:arq.nome,atualizar:$d('#imu').checked});
 const mostra=(r,fim)=>{const n=r.novos+r.atualizados;
  $d('#imr').innerHTML=(fim?`<div class="ok-box"><b>Importação concluída</b> em ${esc(r.empresa)}: ${r.novos} novo(s)${r.atualizados?', '+r.atualizados+' atualizado(s)':''}.</div>`:`<div class="hint">Aba lida: <b>${esc(r.aba)}</b> · colunas reconhecidas: ${Object.entries(r.colunas).filter(([k,v])=>v).map(([k,v])=>esc(k)+' ← “'+esc(v)+'”').join(' · ')}</div>`)+
  kp([[r.total,'Linhas lidas'],[r.novos,'Novos'],[r.atualizados,'A atualizar'],[r.ignorados,'Já cadastrados'],[r.erros_total,'Com erro']])+
  (r.amostra.length&&!fim?`<h4 style="margin:6px 0">Prévia</h4>${tbl(['Ação','Nome','CPF','Detalhes'],r.amostra.map(a=>`<tr><td>${tag(a.acao==='Novo'?0:1,a.acao)}</td><td>${esc(a.nome)}</td><td>${esc(a.cpf)}</td><td>${esc(a.detalhe)}</td></tr>`))}`:'')+
  (r.erros_total?`<h4 style="margin:10px 0 6px">Linhas com erro (não serão importadas)${r.erros_total>r.erros.length?' · mostrando '+r.erros.length+' de '+r.erros_total:''}</h4>${tbl(['Linha','Nome','Motivo'],r.erros.map(e=>`<tr><td>${e.linha}</td><td>${esc(e.nome)}</td><td>${esc(e.motivo)}</td></tr>`))}`:'');
  $d('#imok').disabled=fim||n===0;$d('#imok').textContent=fim?'Concluído':n?`Importar ${n} registro(s)`:'Nada a importar';if(fim){$d('#ima').disabled=true;$d('#imf').value='';arq=null}};
