 const st=Math.max(1,Math.ceil(n/12));ms.forEach((m,i)=>{if(i%st===0||i===n-1)g+=`<text x="${x(i)}" y="${H-12}" text-anchor="middle" font-size="11" fill="#5b6b7b">${m.n<1?'pré':'M'+m.n}</text>`});
 for(const s of series){if(s.t==='bar'){ms.forEach((m,i)=>{const v=s.f(m);if(v==null)return;const y0=y(0),y1=y(v);g+=`<rect x="${x(i)-bw/2}" y="${Math.min(y0,y1)}" width="${bw}" height="${Math.max(1,Math.abs(y0-y1))}" fill="${v<0?'#c0392b':s.c}" rx="1.5"><title>${esc(rotM(m)+' · '+s.l+': '+brl(v))}</title></rect>`})}
  else{let d='',pen=false;ms.forEach((m,i)=>{const v=s.f(m);if(v==null){pen=false;return}d+=(pen?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1);pen=true});g+=`<path d="${d}" fill="none" stroke="${s.c}" stroke-width="${s.dash?1.8:2.4}"${s.dash?' stroke-dasharray="6 4"':''}/>`;
   ms.forEach((m,i)=>{const v=s.f(m);if(v!=null)g+=`<circle cx="${x(i)}" cy="${y(v)}" r="${n<=14?3.2:4}" fill="${n<=14?s.c:'transparent'}"><title>${esc(rotM(m)+' · '+s.l+': '+(o.raw?v:brl(v)))}</title></circle>`})}}
